insert into public.problems (id, title, statement, input_spec, output_spec, notes, examples, tags, rating, time_limit_ms, visibility) values (1219, 'Coin Ways', 'In how many different ways can you pay exactly S using coins of the given values? You have as many coins of each value as you want. Two ways are different if some value is used a different number of times; the order of the coins does not matter. Print the answer modulo 1 000 000 007.', 'The first line contains k and S (1 ≤ k ≤ 50, 0 ≤ S ≤ 10^4). The second line contains k different coin values (1 ≤ c_i ≤ 10^4).', 'Print the number of ways modulo 10^9 + 7.', '', '[{"input":"3 5\n1 2 5\n","output":"4"},{"input":"1 3\n2\n","output":"0"}]'::jsonb, array['dp']::text[], 1500, 2000, 'public') on conflict (id) do nothing;
