insert into public.problems (id, title, statement, input_spec, output_spec, notes, examples, tags, rating, time_limit_ms, visibility) values (1221, 'Light Backpack', 'You have n items; item i weighs w_i and is worth v_i. Your backpack can carry a total weight of at most W. Each item can be taken at most once. What is the largest total value you can carry?', 'The first line contains n and W (1 ≤ n ≤ 100, 1 ≤ W ≤ 5000). Each of the next n lines contains w_i and v_i (1 ≤ w_i ≤ 5000, 1 ≤ v_i ≤ 10^9).', 'Print the largest total value.', '', '[{"input":"3 5\n2 3\n3 4\n4 5\n","output":"7"},{"input":"1 3\n4 100\n","output":"0"}]'::jsonb, array['dp']::text[], 1600, 2000, 'public') on conflict (id) do nothing;
